  9	import com.pousadamarealta.service.PricingService;
 10	import com.pousadamarealta.service.ReportService;
 11	import com.pousadamarealta.service.ReservationService;
 12	import io.javalin.Javalin;
 13	
 14	public class App {
 15	    public static void main(String[] args) throws Exception {
 16	        String dbUrl = System.getenv("DB_URL");
 17	        String dbUser = System.getenv("DB_USER");
 18	        String dbPassword = System.getenv("DB_PASSWORD");
 19	        String portStr = System.getenv("PORT");
 20	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 21	
 22	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 23	            System.err.println("Missing environment variables: DB_URL, DB_USER, DB_PASSWORD");
 24	            System.exit(1);
 25	        }
 26	
 27	        Database database = Database.getInstance(dbUrl, dbUser, dbPassword);
 28	        database.initialize();
 29	
 30	        RoomRepository roomRepository = new RoomRepository(database);
 31	        ReservationRepository reservationRepository = new ReservationRepository(database);
 32	        MessageRepository messageRepository = new MessageRepository(database);
 33	
 34	        PricingService pricingService = new PricingService();
 35	        MessageService messageService = new MessageService(messageRepository);
 36	        ReservationService reservationService = new ReservationService(
 37	            reservationRepository, roomRepository, pricingService, messageService
 38	        );
 39	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 40	
 41	        Javalin app = Javalin.create()
 42	            .start(port);
 43	
 44	        ApiRouter apiRouter = new ApiRouter(
 45	            app, roomRepository, reservationRepository, messageRepository,
 46	            pricingService, reservationService, messageService, reportService
 47	        );
 48	        apiRouter.setupRoutes();
 49	
 50	        System.out.println("Server running on port " + port);
 51	    }
 52	}
 53	package com.pousadamarealta.api;
 54	
 55	import com.fasterxml.jackson.databind.ObjectMapper;
 56	import com.pousadamarealta.db.MessageRepository;
 57	import com.pousadamarealta.db.ReservationRepository;
 58	import com.pousadamarealta.db.RoomRepository;
 59	import com.pousadamarealta.model.Message;
 60	import com.pousadamarealta.model.Reservation;
 61	import com.pousadamarealta.service.MessageService;
 62	import com.pousadamarealta.service.PricingService;
 63	import com.pousadamarealta.service.ReportService;
 64	import com.pousadamarealta.service.ReservationService;
 65	import io.javalin.Javalin;
 66	import io.javalin.http.Context;
 67	import java.math.BigDecimal;
 68	import java.time.LocalDate;
 69	import java.util.HashMap;
 70	import java.util.List;
 71	import java.util.Map;
 72	
 73	public class ApiRouter {
 74	    private final Javalin app;
 75	    private final RoomRepository roomRepository;
 76	    private final ReservationRepository reservationRepository;
 77	    private final MessageRepository messageRepository;
 78	    private final PricingService pricingService;
 79	    private final ReservationService reservationService;
 80	    private final MessageService messageService;
 81	    private final ReportService reportService;
 82	    private final ObjectMapper objectMapper;
 83	
 84	    public ApiRouter(Javalin app, RoomRepository roomRepository, ReservationRepository reservationRepository,
 85	                    MessageRepository messageRepository, PricingService pricingService,
 86	                    ReservationService reservationService, MessageService messageService,
 87	                    ReportService reportService) {
 88	        this.app = app;
 89	        this.roomRepository = roomRepository;
 90	        this.reservationRepository = reservationRepository;
 91	        this.messageRepository = messageRepository;
 92	        this.pricingService = pricingService;
 93	        this.reservationService = reservationService;
 94	        this.messageService = messageService;
 95	        this.reportService = reportService;
 96	        this.objectMapper = new ObjectMapper();
 97	    }
 98	
 99	    public void setupRoutes() {
100	        app.get("/rooms", this::getRooms);
101	        app.post("/reservations", this::createReservation);
102	        app.get("/reservations/{id}", this::getReservation);
103	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
104	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
105	        app.post("/reservations/{id}/check-in", this::checkIn);
106	        app.post("/reservations/{id}/check-out", this::checkOut);
107	        app.get("/reservations/{id}/document", this::getDocument);
108	        app.get("/messages", this::getMessages);
109	        app.get("/reports/occupancy", this::getOccupancyReport);
110	        app.get("/reports/revenue", this::getRevenueReport);
111	    }
112	
113	    private void getRooms(Context ctx) {
114	        try {
115	            List<com.pousadamarealta.model.Room> rooms = roomRepository.findAll();
116	            List<Map<String, Object>> roomList = rooms.stream().map(room -> {
117	                Map<String, Object> map = new HashMap<>();
118	                map.put("number", room.number());
119	                map.put("type", room.type());
120	                map.put("capacity", room.capacity());
121	                map.put("nightlyRate", room.nightlyRate());
122	                return map;
123	            }).toList();
124	            ctx.json(roomList);
125	        } catch (Exception e) {
126	            errorResponse(ctx, 500, "INTERNAL_ERROR", e.getMessage());
127	        }
128	    }
129	
130	    private void createReservation(Context ctx) {
131	        try {
132	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
133	            Integer roomNumber = ((Number) body.get("roomNumber")).intValue();
134	            String guestName = (String) body.get("guestName");
135	            String guestEmail = (String) body.get("guestEmail");
136	            String guestCpf = (String) body.get("guestCpf");
137	            String checkInStr = (String) body.get("checkIn");
138	            String checkOutStr = (String) body.get("checkOut");
139	            Integer guests = ((Number) body.get("guests")).intValue();
140	            String ratePlan = (String) body.get("ratePlan");
141	
142	            if (roomNumber == null || guestName == null || guestEmail == null || guestCpf == null ||
143	                checkInStr == null || checkOutStr == null || guests == null || ratePlan == null) {
144	                errorResponse(ctx, 400, "INVALID_REQUEST", "Missing required fields");
145	                return;
146	            }
147	
148	            LocalDate checkIn = LocalDate.parse(checkInStr);
149	            LocalDate checkOut = LocalDate.parse(checkOutStr);
150	
151	            Reservation reservation = reservationService.createReservation(
152	                roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan
153	            );
154	
155	            ctx.status(201).json(reservationToMap(reservation));
156	        } catch (IllegalArgumentException e) {
157	            handleReservationError(ctx, e.getMessage());
158	        } catch (Exception e) {
159	            errorResponse(ctx, 400, "INVALID_REQUEST", e.getMessage());
160	        }
161	    }
162	
163	    private void getReservation(Context ctx) {
164	        try {
165	            Long id = Long.parseLong(ctx.pathParam("id"));
166	            Reservation reservation = reservationRepository.findById(id)
167	                .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
168	            ctx.json(reservationToMap(reservation));
169	        } catch (IllegalArgumentException e) {
170	            handleReservationError(ctx, e.getMessage());
171	        } catch (Exception e) {
172	            errorResponse(ctx, 400, "INVALID_REQUEST", e.getMessage());
173	        }
174	    }
175	
176	    private void confirmReservation(Context ctx) {
177	        try {
178	            Long id = Long.parseLong(ctx.pathParam("id"));
179	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
180	            BigDecimal amountPaid = new BigDecimal(body.get("amountPaid").toString());
181	
182	            Reservation reservation = reservationService.confirmReservation(id, amountPaid);
183	            ctx.json(reservationToMap(reservation));
184	        } catch (IllegalArgumentException e) {
185	            handleReservationError(ctx, e.getMessage());
186	        } catch (Exception e) {
187	            errorResponse(ctx, 400, "INVALID_REQUEST", e.getMessage());
188	        }
189	    }
190	
191	    private void cancelReservation(Context ctx) {
192	        try {
193	            Long id = Long.parseLong(ctx.pathParam("id"));
194	            Reservation reservation = reservationService.cancelReservation(id);
195	            ctx.json(reservationToMap(reservation));
196	        } catch (IllegalArgumentException e) {
197	            handleReservationError(ctx, e.getMessage());
198	        } catch (Exception e) {
199	            errorResponse(ctx, 400, "INVALID_REQUEST", e.getMessage());
200	        }
201	    }
202	
203	    private void checkIn(Context ctx) {
204	        try {
205	            Long id = Long.parseLong(ctx.pathParam("id"));
206	            Reservation reservation = reservationService.checkIn(id);
207	            ctx.json(reservationToMap(reservation));
208	        } catch (IllegalArgumentException e) {
209	            handleReservationError(ctx, e.getMessage());
210	        } catch (Exception e) {
211	            errorResponse(ctx, 400, "INVALID_REQUEST", e.getMessage());
212	        }
213	    }
214	
215	    private void checkOut(Context ctx) {
216	        try {
217	            Long id = Long.parseLong(ctx.pathParam("id"));
218	            Reservation reservation = reservationService.checkOut(id);
219	            com.pousadamarealta.model.Room room = roomRepository.findByNumber(reservation.getRoomNumber()).get();
220	            String receipt = reservationService.generateReceipt(reservation, room);
221	
222	            Map<String, Object> result = new HashMap<>();
223	            result.put("title", "Comprovante de reserva");
224	            result.put("reservationId", reservation.getId());
225	            result.put("guestName", reservation.getGuestName());
226	            result.put("guestCpf", formatCpf(reservation.getGuestCpf()));
227	            result.put("roomNumber", reservation.getRoomNumber());
228	            result.put("roomType", room.type());
229	            result.put("checkIn", reservation.getCheckIn().toString());
230	            result.put("checkOut", reservation.getCheckOut().toString());
231	            result.put("nights", reservation.getNights());
232	            result.put("subtotal", reservation.getSubtotal());
233	            result.put("discount", reservation.getDiscount());
234	            result.put("total", reservation.getTotal());
235	
236	            ctx.json(result);
237	        } catch (IllegalArgumentException e) {
238	            handleReservationError(ctx, e.getMessage());
239	        } catch (Exception e) {
240	            errorResponse(ctx, 400, "INVALID_REQUEST", e.getMessage());
241	        }
242	    }
243	
244	    private void getDocument(Context ctx) {
245	        try {
246	            Long id = Long.parseLong(ctx.pathParam("id"));
247	            Reservation reservation = reservationRepository.findById(id)
248	                .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
249	
250	            if (!("CONFIRMED".equals(reservation.getStatus()) || "CHECKED_IN".equals(reservation.getStatus()) ||
251	                  "CHECKED_OUT".equals(reservation.getStatus()))) {
252	                errorResponse(ctx, 409, "OPERATION_NOT_ALLOWED", "Document only available for paid reservations");
253	                return;
254	            }
255	
256	            com.pousadamarealta.model.Room room = roomRepository.findByNumber(reservation.getRoomNumber()).get();
257	            String receipt = reservationService.generateReceipt(reservation, room);
258	
259	            Map<String, Object> result = new HashMap<>();
260	            result.put("title", "Comprovante de reserva");
261	            result.put("reservationId", reservation.getId());
262	            result.put("guestName", reservation.getGuestName());
263	            result.put("guestCpf", formatCpf(reservation.getGuestCpf()));
264	            result.put("roomNumber", reservation.getRoomNumber());
265	            result.put("roomType", room.type());
266	            result.put("checkIn", reservation.getCheckIn().toString());
267	            result.put("checkOut", reservation.getCheckOut().toString());
268	            result.put("nights", reservation.getNights());
269	            result.put("subtotal", reservation.getSubtotal());
270	            result.put("discount", reservation.getDiscount());
271	            result.put("total", reservation.getTotal());
272	
273	            ctx.json(result);
274	        } catch (IllegalArgumentException e) {
275	            handleReservationError(ctx, e.getMessage());
276	        } catch (Exception e) {
277	            errorResponse(ctx, 400, "INVALID_REQUEST", e.getMessage());
278	        }
279	    }
280	
281	    private void getMessages(Context ctx) {
282	        try {
283	            List<Message> messages = messageRepository.findAll();
284	            List<Map<String, Object>> messageList = messages.stream().map(msg -> {
285	                Map<String, Object> map = new HashMap<>();
286	                map.put("id", msg.getId());
287	                map.put("channel", msg.getChannel());
288	                map.put("to", msg.getTo());
289	                map.put("subject", msg.getSubject());
290	                map.put("body", msg.getBody());
291	                map.put("status", msg.getStatus());
292	                return map;
293	            }).toList();
294	            ctx.json(messageList);
295	        } catch (Exception e) {
296	            errorResponse(ctx, 500, "INTERNAL_ERROR", e.getMessage());
297	        }
298	    }
299	
300	    private void getOccupancyReport(Context ctx) {
301	        try {
302	            String dateStr = ctx.queryParam("date");
303	            if (dateStr == null) {
304	                errorResponse(ctx, 400, "INVALID_REQUEST", "Missing date parameter");
305	                return;
306	            }
307	            LocalDate date = LocalDate.parse(dateStr);
308	            String report = reportService.generateOccupancyReport(date);
309	            ctx.header("Content-Type", "text/csv; charset=utf-8");
310	            ctx.result(report);
311	        } catch (Exception e) {
312	            errorResponse(ctx, 400, "INVALID_REQUEST", e.getMessage());
313	        }
314	    }
315	
316	    private void getRevenueReport(Context ctx) {
317	        try {
318	            String monthStr = ctx.queryParam("month");
319	            if (monthStr == null) {
320	                errorResponse(ctx, 400, "INVALID_REQUEST", "Missing month parameter");
321	                return;
322	            }
323	            String[] parts = monthStr.split("-");
324	            int year = Integer.parseInt(parts[0]);
325	            int month = Integer.parseInt(parts[1]);
326	            String report = reportService.generateRevenueReport(year, month);
327	            ctx.header("Content-Type", "text/csv; charset=utf-8");
328	            ctx.result(report);
329	        } catch (Exception e) {
330	            errorResponse(ctx, 400, "INVALID_REQUEST", e.getMessage());
331	        }
332	    }
333	
334	    private void handleReservationError(Context ctx, String error) {
335	        switch (error) {
336	            case "ROOM_NOT_FOUND" -> errorResponse(ctx, 404, "ROOM_NOT_FOUND", "Room not found");
337	            case "RESERVATION_NOT_FOUND" -> errorResponse(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
338	            case "ROOM_UNAVAILABLE" -> errorResponse(ctx, 409, "ROOM_UNAVAILABLE", "Room is not available for these dates");
339	            case "CAPACITY_EXCEEDED" -> errorResponse(ctx, 422, "CAPACITY_EXCEEDED", "Guest count exceeds room capacity");
340	            case "OPERATION_NOT_ALLOWED" -> errorResponse(ctx, 409, "OPERATION_NOT_ALLOWED", "Operation not allowed for this reservation status");
341	            default -> errorResponse(ctx, 400, "INVALID_REQUEST", error);
342	        }
343	    }
344	
345	    private void errorResponse(Context ctx, int status, String error, String message) {
346	        ctx.status(status);
347	        Map<String, String> errorMap = new HashMap<>();
348	        errorMap.put("error", error);
349	        errorMap.put("message", message);
350	        ctx.json(errorMap);
351	    }
352	
353	    private Map<String, Object> reservationToMap(Reservation r) {
354	        Map<String, Object> map = new HashMap<>();
355	        map.put("id", r.getId());
356	        map.put("roomNumber", r.getRoomNumber());
357	        map.put("guestName", r.getGuestName());
358	        map.put("guestEmail", r.getGuestEmail());
359	        map.put("guestCpf", r.getGuestCpf());
360	        map.put("checkIn", r.getCheckIn().toString());
361	        map.put("checkOut", r.getCheckOut().toString());
362	        map.put("guests", r.getGuests());
363	        map.put("ratePlan", r.getRatePlan());
364	        map.put("nights", r.getNights());
365	        map.put("subtotal", r.getSubtotal());
366	        map.put("discount", r.getDiscount());
367	        map.put("total", r.getTotal());
368	        map.put("status", r.getStatus());
369	        map.put("amountPaid", r.getAmountPaid());
370	        map.put("refund", r.getRefund());
371	        return map;
372	    }
373	
374	    private String formatCpf(String cpf) {
375	        if (cpf == null || cpf.length() != 11) {
376	            return cpf;
377	        }
378	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
379	    }
380	}

