355	        map.put("id", r.getId());
356	        map.put("roomNumber", r.getRoomNumber());
357	        map.put("guestName", r.getGuestName());
358	        map.put("guestEmail", r.getGuestEmail());
359	        map.put("guestCpf", r.getGuestCpf());
360	        map.put("checkIn", r.getCheckIn().toString());
361	        map.put("checkOut", r.getCheckOut().toString());
362	        map.put("guests", r.getGuests());
363	        map.put("ratePlan", r.getRatePlan());
364	        map.put("nights", r.getNights());
365	        map.put("subtotal", r.getSubtotal());
366	        map.put("discount", r.getDiscount());
367	        map.put("total", r.getTotal());
368	        map.put("status", r.getStatus());
369	        map.put("amountPaid", r.getAmountPaid());
370	        map.put("refund", r.getRefund());
371	        return map;
372	    }
373	
374	    private String formatCpf(String cpf) {
375	        if (cpf == null || cpf.length() != 11) {
376	            return cpf;
377	        }
378	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
379	    }
380	}

