  9	public class MessageService {
 10	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@]+@[^@]+\\.[^@]+$");
 11	    private static final String ARCHIVE_EMAIL = "arquivo@pousadamarealta.com.br";
 12	    private static final String TEST_EMAIL = "testes@pousadamarealta.com.br";
