 21	    public List<Message> sendMessage(String originalTo, String subject, String body) throws Exception {
 22	        List<Message> sentMessages = new ArrayList<>();
 23	
 24	        if (!isValidEmail(originalTo)) {
 25	            Message blockedMessage = new Message(null, "EMAIL", originalTo, subject, body, "BLOCKED");
 26	            messageRepository.save(blockedMessage);
 27	            sentMessages.add(blockedMessage);
 28	            return sentMessages;
 29	        }
 30	
 31	        String recipientEmail = originalTo;
 32	        String finalSubject = subject;
 33	        String finalBody = body;
 34	
 35	        if (IS_TEST_MODE) {
 36	            recipientEmail = TEST_EMAIL;
 37	            finalSubject = "[TESTE] " + subject;
 38	            finalBody = "Destinatário original: " + originalTo + "\n\n" + body;
 39	        }
 40	
 41	        Message mainMessage = new Message(null, "EMAIL", recipientEmail, finalSubject, finalBody, "SENT");
 42	        messageRepository.save(mainMessage);
 43	        sentMessages.add(mainMessage);
 44	
 45	        if (!IS_TEST_MODE) {
 46	            Message archiveMessage = new Message(
 47	                null,
 48	                "EMAIL",
 49	                ARCHIVE_EMAIL,
 50	                "[Cópia] " + subject,
 51	                body,
 52	                "SENT"
 53	            );
 54	            messageRepository.save(archiveMessage);
 55	            sentMessages.add(archiveMessage);
 56	        }
 57	
 58	        return sentMessages;
 59	    }
 60	
 61	    private boolean isValidEmail(String email) {
 62	        if (email == null || email.isBlank()) {
 63	            return false;
 64	        }
 65	        return EMAIL_PATTERN.matcher(email).matches();
 66	    }
