 68	package com.pousadamarealta.service;
 69	
 70	import java.math.BigDecimal;
 71	import java.math.RoundingMode;
 72	import java.time.LocalDate;
 73	import java.time.Month;
 74	
 75	public class PricingService {
 76	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
 77	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
 78	
 79	    public BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate date) {
 80	        BigDecimal price = baseRate;
 81	        if (isHighSeason(date)) {
 82	            price = baseRate.multiply(HIGH_SEASON_MULTIPLIER);
 83	        }
 84	        return roundBankersStyle(price);
 85	    }
 86	
 87	    public BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
 88	        BigDecimal subtotal = BigDecimal.ZERO;
 89	        LocalDate current = checkIn;
 90	        while (current.isBefore(checkOut)) {
 91	            BigDecimal nightlyPrice = calculateNightlyPrice(baseRate, current);
 92	            nightlyPrice = roundBankersStyle(nightlyPrice);
 93	            subtotal = subtotal.add(nightlyPrice);
 94	            current = current.plusDays(1);
 95	        }
 96	        return subtotal;
 97	    }
 98	
 99	    public BigDecimal calculateDiscount(BigDecimal subtotal, String ratePlan) {
100	        if ("NON_REFUNDABLE".equals(ratePlan)) {
101	            return roundBankersStyle(subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE));
102	        }
103	        return BigDecimal.ZERO;
104	    }
105	
106	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
107	        return subtotal.subtract(discount);
108	    }
109	
110	    public int calculateNights(LocalDate checkIn, LocalDate checkOut) {
111	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
112	    }
113	
114	    private boolean isHighSeason(LocalDate date) {
115	        Month month = date.getMonth();
116	        int dayOfMonth = date.getDayOfMonth();
117	
118	        if (month == Month.JULY) {
119	            return true;
120	        }
121	
122	        if (month == Month.DECEMBER) {
123	            return dayOfMonth >= 15;
124	        }
125	
126	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
127	            return true;
128	        }
129	
130	        return false;
131	    }
132	
133	    public BigDecimal roundBankersStyle(BigDecimal value) {
134	        return value.setScale(2, RoundingMode.HALF_EVEN);
135	    }
136	}
