159	    public String generateOccupancyReport(LocalDate date) throws Exception {
160	        List<Reservation> reservations = reservationRepository.findByDateForOccupancy(date);
161	        Map<Integer, Room> roomMap = buildRoomMap();
162	
163	        StringBuilder csv = new StringBuilder();
164	        csv.append("room,type,reservation,check_in,check_out\n");
165	
166	        for (Reservation res : reservations) {
167	            Room room = roomMap.get(res.getRoomNumber());
168	            if (room != null) {
