170	                csv.append(room.type()).append(",");
171	                csv.append(res.getId()).append(",");
172	                csv.append(formatDate(res.getCheckIn())).append(",");
173	                csv.append(formatDate(res.getCheckOut())).append("\n");
174	            }
175	        }
176	
177	        int occupiedRooms = reservations.size();
178	        int totalRooms = roomMap.size();
179	        csv.append("total,").append(occupiedRooms).append("/").append(totalRooms);
180	
181	        return csv.toString();
182	    }
