189	        csv.append("reservation,room,check_in,check_out,status,amount\n");
190	
191	        BigDecimal totalAmount = BigDecimal.ZERO;
192	
193	        for (Reservation res : reservations) {
194	            BigDecimal amount = res.getAmountPaid();
195	            if (res.getRefund() != null) {
196	                amount = amount.subtract(res.getRefund());
197	            }
198	
199	            csv.append(res.getId()).append(",");
200	            csv.append(res.getRoomNumber()).append(",");
201	            csv.append(formatDate(res.getCheckIn())).append(",");
202	            csv.append(formatDate(res.getCheckOut())).append(",");
203	            csv.append(res.getStatus()).append(",");
204	            csv.append(formatMoney(amount)).append("\n");
205	
206	            totalAmount = totalAmount.add(amount);
207	        }
208	
209	        csv.append("total,").append(formatMoney(totalAmount));
210	
211	        return csv.toString();
212	    }
