214	    private Map<Integer, Room> buildRoomMap() throws Exception {
215	        Map<Integer, Room> map = new HashMap<>();
216	        for (Room room : roomRepository.findAll()) {
217	            map.put(room.number(), room);
218	        }
219	        return map;
220	    }
