254	    public Reservation createReservation(Integer roomNumber, String guestName, String guestEmail, String guestCpf,
255	                                         LocalDate checkIn, LocalDate checkOut, Integer guests, String ratePlan)
256	            throws Exception {
257	        validateReservationInput(roomNumber, checkIn, checkOut, guests);
258	
259	        Room room = roomRepository.findByNumber(roomNumber)
260	            .orElseThrow(() -> new IllegalArgumentException("ROOM_NOT_FOUND"));
261	
262	        if (guests > room.capacity()) {
263	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
264	        }
265	
266	        checkRoomAvailability(roomNumber, checkIn, checkOut);
267	
268	        int nights = pricingService.calculateNights(checkIn, checkOut);
269	        BigDecimal subtotal = pricingService.calculateSubtotal(room.nightlyRate(), checkIn, checkOut);
270	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
271	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
272	
273	        Reservation reservation = new Reservation();
