283	        reservation.setSubtotal(subtotal);
284	        reservation.setDiscount(discount);
285	        reservation.setTotal(total);
286	        reservation.setStatus("PENDING");
287	        reservation.setAmountPaid(BigDecimal.ZERO);
288	
289	        return reservationRepository.save(reservation);
