294	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
295	
296	        if (!"PENDING".equals(reservation.getStatus())) {
297	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
298	        }
299	
300	        reservation.setStatus("CONFIRMED");
301	        reservation.setAmountPaid(amountPaid);
