314	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
315	
316	        if (!"CONFIRMED".equals(reservation.getStatus())) {
317	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
318	        }
