340	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
341	
342	        if (!"PENDING".equals(reservation.getStatus()) && !"CONFIRMED".equals(reservation.getStatus())) {
343	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
344	        }
345	
346	        BigDecimal refund = BigDecimal.ZERO;
347	        if ("CONFIRMED".equals(reservation.getStatus()) && "STANDARD".equals(reservation.getRatePlan())) {
348	            refund = reservation.getAmountPaid();
349	        }
350	
351	        reservation.setStatus("CANCELLED");
352	        reservation.setRefund(refund);
