360	        sb.append("Hóspede: ").append(reservation.getGuestName()).append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
361	        sb.append("Quarto: ").append(reservation.getRoomNumber()).append(" (").append(room.type()).append(")\n");
362	        sb.append("Entrada: ").append(formatDate(reservation.getCheckIn())).append(" | ");
