364	        sb.append(reservation.getNights()).append(" ").append(reservation.getNights() == 1 ? "diária" : "diárias").append("\n");
365	        sb.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
366	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
367	            sb.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
368	        }
369	        sb.append("Total: ").append(formatMoney(reservation.getTotal())).append("\n");
370	        return sb.toString();
