  8	public class Database {
  9	    private static Database instance;
 10	    private final String url;
 11	    private final String user;
 12	    private final String password;
 13	
 14	    public Database(String url, String user, String password) {
 15	        this.url = url;
 16	        this.user = user;
 17	        this.password = password;
 18	    }
 19	
 20	    public static Database getInstance(String url, String user, String password) {
 21	        if (instance == null) {
 22	            instance = new Database(url, user, password);
 23	        }
 24	        return instance;
 25	    }
 26	
 27	    public Connection getConnection() throws SQLException {
 28	        return DriverManager.getConnection(url, user, password);
 29	    }
 30	
 31	    public void initialize() throws SQLException {
 32	        try (Connection conn = getConnection()) {
 33	            try (Statement stmt = conn.createStatement()) {
 34	                createTables(stmt);
 35	                insertRooms(stmt);
 36	            }
 37	        }
 38	    }
 39	
 40	    private void createTables(Statement stmt) throws SQLException {
 41	        stmt.execute("""
 42	            CREATE TABLE IF NOT EXISTS rooms (
 43	                number INTEGER PRIMARY KEY,
 44	                type VARCHAR(50) NOT NULL,
 45	                capacity INTEGER NOT NULL,
 46	                nightly_rate DECIMAL(10, 2) NOT NULL
 47	            )
 48	        """);
 49	
 50	        stmt.execute("""
 51	            CREATE TABLE IF NOT EXISTS reservations (
 52	                id SERIAL PRIMARY KEY,
 53	                room_number INTEGER NOT NULL,
 54	                guest_name VARCHAR(255) NOT NULL,
 55	                guest_email VARCHAR(255) NOT NULL,
 56	                guest_cpf VARCHAR(20) NOT NULL,
 57	                check_in DATE NOT NULL,
