 62	                subtotal DECIMAL(10, 2) NOT NULL,
 63	                discount DECIMAL(10, 2) NOT NULL,
 64	                total DECIMAL(10, 2) NOT NULL,
 65	                status VARCHAR(50) NOT NULL,
 66	                amount_paid DECIMAL(10, 2) DEFAULT 0,
 67	                refund DECIMAL(10, 2),
 68	                FOREIGN KEY (room_number) REFERENCES rooms(number)
 69	            )
 70	        """);
 71	
 72	        stmt.execute("""
 73	            CREATE TABLE IF NOT EXISTS messages (
 74	                id SERIAL PRIMARY KEY,
 75	                channel VARCHAR(50) NOT NULL,
 76	                to_address VARCHAR(255) NOT NULL,
 77	                subject VARCHAR(500) NOT NULL,
