104	public class MessageRepository {
105	    private final Database database;
106	
107	    public MessageRepository(Database database) {
108	        this.database = database;
109	    }
110	
111	    public Message save(Message message) throws SQLException {
112	        try (Connection conn = database.getConnection();
113	             var stmt = conn.prepareStatement(
114	                "INSERT INTO messages (channel, to_address, subject, body, status) VALUES (?, ?, ?, ?, ?)",
115	                Statement.RETURN_GENERATED_KEYS)) {
116	            stmt.setString(1, message.getChannel());
117	            stmt.setString(2, message.getTo());
118	            stmt.setString(3, message.getSubject());
119	            stmt.setString(4, message.getBody());
120	            stmt.setString(5, message.getStatus());
121	            stmt.executeUpdate();
122	            try (ResultSet generatedKeys = stmt.getGeneratedKeys()) {
123	                if (generatedKeys.next()) {
124	                    message.setId(generatedKeys.getLong(1));
125	                }
126	            }
127	        }
128	        return message;
129	    }
130	
131	    public List<Message> findAll() throws SQLException {
132	        List<Message> messages = new ArrayList<>();
133	        try (Connection conn = database.getConnection();
134	             var stmt = conn.createStatement();
135	             ResultSet rs = stmt.executeQuery("SELECT * FROM messages ORDER BY id")) {
136	            while (rs.next()) {
137	                messages.add(mapResultSetToMessage(rs));
138	            }
139	        }
140	        return messages;
141	    }
142	
143	    private Message mapResultSetToMessage(ResultSet rs) throws SQLException {
144	        return new Message(
145	            rs.getLong("id"),
146	            rs.getString("channel"),
147	            rs.getString("to_address"),
148	            rs.getString("subject"),
