273	            stmt.setDate(2, Date.valueOf(date));
274	            try (ResultSet rs = stmt.executeQuery()) {
275	                while (rs.next()) {
276	                    reservations.add(mapResultSetToReservation(rs));
277	                }
278	            }
279	        }
280	        return reservations;
