283	    private void setReservationStatement(PreparedStatement stmt, Reservation r) throws SQLException {
284	        stmt.setInt(1, r.getRoomNumber());
285	        stmt.setString(2, r.getGuestName());
286	        stmt.setString(3, r.getGuestEmail());
