337	        this.database = database;
338	    }
339	
340	    public List<Room> findAll() throws SQLException {
341	        List<Room> rooms = new ArrayList<>();
342	        try (Connection conn = database.getConnection();
343	             var stmt = conn.createStatement();
344	             ResultSet rs = stmt.executeQuery("SELECT number, type, capacity, nightly_rate FROM rooms ORDER BY number")) {
345	            while (rs.next()) {
346	                rooms.add(new Room(
347	                    rs.getInt("number"),
348	                    rs.getString("type"),
349	                    rs.getInt("capacity"),
350	                    rs.getBigDecimal("nightly_rate")
351	                ));
352	            }
353	        }
354	        return rooms;
355	    }
356	
357	    public Optional<Room> findByNumber(Integer number) throws SQLException {
358	        try (Connection conn = database.getConnection();
359	             var stmt = conn.prepareStatement("SELECT number, type, capacity, nightly_rate FROM rooms WHERE number = ?")) {
360	            stmt.setInt(1, number);
361	            try (ResultSet rs = stmt.executeQuery()) {
362	                if (rs.next()) {
363	                    return Optional.of(new Room(
364	                        rs.getInt("number"),
365	                        rs.getString("type"),
366	                        rs.getInt("capacity"),
367	                        rs.getBigDecimal("nightly_rate")
368	                    ));
369	                }
370	            }
371	        }
372	        return Optional.empty();
373	    }
